from typing import Optional

import pydantic

from ...schemas.rapi.base import BaseRapiResponseSchema


class Calls(pydantic.BaseModel):
    allowTo: str


class Groups(pydantic.BaseModel):
    allowTo: str
    inviteBlacklistSize: Optional[int]


class GetPrivacySettingResultsSchema(pydantic.BaseModel):
    calls: Calls
    groups: Groups


class GetPrivacySettingResponseSchema(BaseRapiResponseSchema):
    results: GetPrivacySettingResultsSchema


class SetUserAgreementResponseSchema(BaseRapiResponseSchema): ...


class UpdatePrivacySettingsResponseSchema(BaseRapiResponseSchema): ...


class Person(pydantic.BaseModel):
    sn: str
    firstName: Optional[str]
    middleName: Optional[str]
    lastName: Optional[str]
    friendly: str
    nick: str


class InviteBlacklistGetResultsSchema(pydantic.BaseModel):
    blacklist: list[str]
    cursor: Optional[str]
    persons: Optional[list[Person]]


class InviteBlacklistGetResponseSchema(BaseRapiResponseSchema):
    results: InviteBlacklistGetResultsSchema


class GetBlacklistedContactsResultsSchema(pydantic.BaseModel):
    blacklist: list[str]
    cursor: Optional[str]


class GetBlacklistedContactsResponseSchema(BaseRapiResponseSchema):
    results: GetBlacklistedContactsResultsSchema


class InviteBlacklistSearchResponseSchema(InviteBlacklistGetResponseSchema): ...


class InviteBlacklistAddResponseSchema(BaseRapiResponseSchema): ...


class InviteBlacklistDelResponseSchema(BaseRapiResponseSchema): ...
